import 'package:flutter/material.dart'; import '../models/models.dart'; import '../providers/app_state.dart'; import '../widgets/common.dart';
class TasksScreen extends StatefulWidget{final AppState state;final void Function(Task) openTask;const TasksScreen({super.key,required this.state,required this.openTask});@override State<TasksScreen> createState()=>_TasksScreenState();}
class _TasksScreenState extends State<TasksScreen>{String q='';TaskStatus? status;@override Widget build(BuildContext c){var tasks=widget.state.workspace.tasks.where((t)=>t.title.toLowerCase().contains(q.toLowerCase())||t.description.toLowerCase().contains(q.toLowerCase())).toList();if(status!=null)tasks=tasks.where((t)=>t.status==status).toList();return ListView(padding:const EdgeInsets.all(24),children:[Row(children:[Expanded(child:Text('Tasks',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w700))),FilledButton.icon(onPressed:(){if(tasks.isNotEmpty)widget.openTask(tasks.first);},icon:const Icon(Icons.add),label:const Text('New task'))]),const SizedBox(height:18),Row(children:[Expanded(child:TextField(onChanged:(v)=>setState(()=>q=v),decoration:const InputDecoration(hintText:'Search tasks...',prefixIcon:Icon(Icons.search)))),const SizedBox(width:12),DropdownButton<TaskStatus?>(value:status,hint:const Text('Filter'),items:[const DropdownMenuItem(value:null,child:Text('All status')), ...TaskStatus.values.map((s)=>DropdownMenuItem(value:s,child:Text(enumName(s))))],onChanged:(v)=>setState(()=>status=v))]),const SizedBox(height:16),GitCard(child:Column(children:[for(final t in tasks)...[TaskRow(task:t,onTap:()=>widget.openTask(t)),if(t!=tasks.last)Divider(height:1)]]))]);}}
